use std::{collections::BTreeMap, path::Path};
use syn::{visit::Visit, Expr, ExprCall, Item, Type};

#[derive(Default)]
struct Builds(BTreeMap<String, usize>);
impl<'ast> Visit<'ast> for Builds {
    fn visit_expr_call(&mut self, call: &'ast ExprCall) {
        if let Expr::Path(callee) = &*call.func {
            if callee.path.segments.last().is_some_and(|s| s.ident == "build" || s.ident == "from_pairs" || s.ident == "new") {
                let path = callee.qself.as_ref().and_then(|q| match &*q.ty {
                    Type::Path(ty) => Some(&ty.path),
                    _ => None,
                }).unwrap_or(&callee.path);
                for segment in &path.segments {
                    let name = segment.ident.to_string();
                    if matches!(name.as_str(), "HashIndex" | "RadixRun" | "SortedRun" | "AdaptiveKeySet" | "PrefixRun") {
                        *self.0.entry(name).or_default() += 1;
                    }
                }
            }
        }
        syn::visit::visit_expr_call(self, call);
    }
}

fn main() {
    let mut result = BTreeMap::new();
    for argument in std::env::args().skip(1) {
        let path = Path::new(&argument);
        let text = std::fs::read_to_string(path).expect("read expanded Rust");
        let file = syn::parse_file(&text).expect("parse expanded Rust");
        let query = file.items.iter().find_map(|item| match item {
            Item::Mod(module) if module.ident == "query" => module.content.as_ref(),
            _ => None,
        }).expect("generated worker has an inline query module");
        let mut configurations = BTreeMap::new();
        for item in &query.1 {
            if let Item::Mod(module) = item {
                let name = module.ident.to_string();
                if matches!(name.as_str(), "default" | "radix" | "radix_retained" | "built_hash" | "built_radix") {
                    assert!(module.content.is_some(), "expanded configuration is inline");
                    let mut builds = Builds::default();
                    builds.visit_item_mod(module);
                    configurations.insert(name, builds.0);
                }
            }
        }
        assert!(configurations.contains_key("default") && configurations.contains_key("radix"));
        result.insert(path.file_stem().unwrap().to_string_lossy().to_string(), configurations);
    }
    println!("{}", serde_json::to_string_pretty(&result).unwrap());
}
